export function searchText(value){return String(value??'').normalize('NFKC').toLowerCase().replace(/no\s*hooks?|无钩/g,'无钩').replace(/hooks?|带钩|钩/g,'钩').replace(/standard/g,'标准').replace(/mini/g,'迷你').replace(/[\s_·.／/—-]+/g,'');}
export function productOf(record){return record.product||(record.custom?'我的标签':'其他标签');}
export function filterLibrary(records,{query='',product='',group=''}={}){const terms=String(query).trim().split(/\s+/).filter(Boolean).map(searchText);return records.filter(r=>(!product||productOf(r)===product)&&(!group||(r.group||'我的标签')===group)&&terms.every(t=>searchText([r.name,r.group,r.product,r.source].join(' ')).includes(t)));}
export function restoreView(value){try{const v=JSON.parse(value);return {id:typeof v.id==='string'?v.id:'',quantity:Number.isSafeInteger(v.quantity)&&v.quantity>0&&v.quantity<=1e9?v.quantity:1000,product:typeof v.product==='string'?v.product:'',group:typeof v.group==='string'?v.group:'',query:typeof v.query==='string'?v.query.slice(0,100):''};}catch{return {id:'',quantity:1000,product:'',group:'',query:''};}}
export function inferGrid(text){const s=String(text).normalize('NFKC');const grid=s.match(/(\d+)\s*列\s*[×xX]\s*(\d+)\s*行/),total=s.match(/共\s*(\d+)\s*[张枚]/);if(!grid||!total)return null;const cols=+grid[1],rows=+grid[2];return cols>0&&rows>0&&cols<=1000&&rows<=1000&&cols*rows===+total[1]?{cols,rows}:null;}
